CREATE TABLE json_document (id INTEGER PRIMARY KEY, schema TEXT NOT NULL, root_value_id INTEGER NOT NULL REFERENCES json_value(id));
CREATE TABLE json_value (id INTEGER PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('null', 'boolean', 'number', 'string', 'array', 'object')), boolean_value INTEGER CHECK(boolean_value IN (0, 1)), number_lexeme TEXT, string_value TEXT, CHECK((kind IN ('null', 'array', 'object') AND boolean_value IS NULL AND number_lexeme IS NULL AND string_value IS NULL) OR (kind = 'boolean' AND boolean_value IS NOT NULL AND number_lexeme IS NULL AND string_value IS NULL) OR (kind = 'number' AND boolean_value IS NULL AND number_lexeme IS NOT NULL AND string_value IS NULL) OR (kind = 'string' AND boolean_value IS NULL AND number_lexeme IS NULL AND string_value IS NOT NULL)));
CREATE TABLE json_object_member (id INTEGER PRIMARY KEY, object_value_id INTEGER NOT NULL REFERENCES json_value(id), ordinal INTEGER NOT NULL CHECK(ordinal >= 0), key TEXT NOT NULL, value_id INTEGER NOT NULL REFERENCES json_value(id));
CREATE TABLE json_array_element (id INTEGER PRIMARY KEY, array_value_id INTEGER NOT NULL REFERENCES json_value(id), ordinal INTEGER NOT NULL CHECK(ordinal >= 0), value_id INTEGER NOT NULL REFERENCES json_value(id));
